mapper.select:
SELECT 
  FROM apr07_alt_appr
       INNER JOIN emp01_person tgt ON tgt.emp01_person_id = apr07_target_emp_id AND tgt.emp01_company_id = #{companyId}
       INNER JOIN emp01_person org ON org.emp01_person_id = apr07_alt_emp_id AND org.emp01_company_id = #{companyId}
 WHERE 1=1

   AND apr07_alt_appr_id NOT IN
    #{item}

 ORDER BY apr07_start_date

SELECT 
  FROM apr07_alt_appr
       INNER JOIN emp01_person tgt ON tgt.emp01_person_id = apr07_target_emp_id
       INNER JOIN emp01_person org ON org.emp01_person_id = apr07_alt_emp_id
 WHERE apr07_alt_appr_id = #{altApprId}
   AND tgt.emp01_company_id = #{companyId}

mapper.delete:
DELETE FROM apr07_alt_appr
 WHERE apr07_alt_appr_id = #{altApprId}
   AND apr07_target_emp_id IN (SELECT emp01_person_id FROM emp01_person WHERE emp01_company_id = #{companyId})
